<span class="line"><span style="color:#E5C07B;">        self</span><span style="color:#ABB2BF;">.n_docs </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> len</span><span style="color:#ABB2BF;">(documents)</span></span>
